//! The client stubs of the `.proto` the crate ships
//! (`crates/grpc-bridge/proto/zerodds/chat/v1/bridge.proto`), generated by
//! tonic-prost-build with `protoc` (PROTOC, else on the PATH).

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../proto");
    let proto = root.join("zerodds/chat/v1/bridge.proto");
    println!("cargo:rerun-if-changed={}", proto.display());
    tonic_prost_build::configure()
        .build_server(false)
        .compile_protos(&[proto], &[root])?;
    Ok(())
}
